  font-display: swap;
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;  /* latin-ext: Š Ž Ł ő ğ and the rest of Latin Extended */
}

:root {
  --accent: #6C4CF1;                 /* the one accent — pills, bars, dots */
  --text-color: #ffffff;                 /* primary text */
  --text-dim: rgba(255, 255, 255, 0.72);  /* secondary line */
  --panel-bg: rgba(30, 26, 44, 0.94);    /* the dark gray-violet strap */
  --font-heading: "Outfit", Arial, sans-serif; /* one family; weight makes the hierarchy */
  --font-numeric: "Outfit", Arial, sans-serif; /* Outfit's digits are tabular — clocks hold width */
  --scale: 1;                               /* whole-graphic size (resolution folds in here) */
  --type-scale: 1;                          /* text-only size knob */
}

/* Transparent 1920x1080 stage — a broadcast graphic renders over video. */
* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: transparent;
  font-family: var(--font-heading);
}

#ticker-stage {
  position: absolute;
  inset: 0;
  opacity: 0;                                    /* hidden until play() */
}

/* The data holder — a hidden source, never painted. */
.ticker-source { display: none; }

/* The bar: full frame width, flush at the very bottom — frame-anchored geometry, so it is
   sized against the frame, never against its text. */
.ticker-bar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: calc(66px * var(--scale));
  display: flex;
  align-items: stretch;
  background: #ffffff;
  box-shadow: 0 -10px 34px rgba(0, 0, 0, 0.28); /* lifts the white bar off the picture */
  will-change: transform;
}

/* The violet label block on the left. */
.ticker-label {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  padding: 0 calc(28px * var(--scale));
  background: var(--accent);
}
.ticker-label span {
  font-size: calc(22px * var(--scale) * var(--type-scale));
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-color);
}

/* The headline window — one item at a time, pushed vertically. */
.ticker-window {
  flex: 1;
  display: flex;
  align-items: center;
  overflow: hidden;                              /* the push happens behind this mask */
  padding: 0 calc(30px * var(--scale));
  min-width: 0;
}
.ticker-item {
  font-size: calc(26px * var(--scale) * var(--type-scale));
  font-weight: 500;
  line-height: 1.2;
  color: #17131f;
  white-space: nowrap;                           /* a headline is one line on the bar */
  overflow: hidden;
  text-overflow: ellipsis;                       /* an extreme line trims, never collides */
  max-width: 100%;
  will-change: transform, opacity;
}

/* The clock — quiet, tabular, separated by a hairline. */
.ticker-clock {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  padding: 0 calc(28px * var(--scale));
  border-left: 1px solid rgba(23, 19, 31, 0.14); /* hairline separator */
}
.ticker-clock span {
  font-family: var(--font-numeric);              /* digits all one width… */
  font-variant-numeric: tabular-nums;            /* …and asked for explicitly */
  font-size: calc(24px * var(--scale) * var(--type-scale));
  font-weight: 600;
  color: rgba(23, 19, 31, 0.6);
}

